/* From Uiverse.io by vinodjangid07 - Tags: input */
.__UIV_SCOPE__ .inputContainer {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.__UIV_SCOPE__ #inputField {
  border: 2px solid white;
  background-color: transparent;
  border-radius: 10px;
  padding: 12px 15px;
  color: black;
  font-weight: 500;
  outline: none;
  caret-color: rgb(155, 78, 255);
  transition-duration: .3s;
  font-family: Whitney, -apple-system, BlinkMacSystemFont, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
}

.__UIV_SCOPE__ .userIcon {
  position: absolute;
  fill: rgb(155, 78, 255);
  width: 12px;
  top: -23px;
  left: -15px;
  opacity: 0;
  transition: .2s linear;
}

.__UIV_SCOPE__ .usernameLabel {
  position: absolute;
  top: -25px;
  left: 5px;
  color: white;
  font-size: 14px;
  font-weight: 400;
  font-family: Whitney, -apple-system, BlinkMacSystemFont, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
  overflow: hidden;
  transition: .2s linear;
  opacity: 0;
}

.__UIV_SCOPE__ #inputField:focus ~ .usernameLabel,
.__UIV_SCOPE__ #inputField:valid ~ .usernameLabel {
  transform: translateX(20px);
  opacity: 1;
}

.__UIV_SCOPE__ #inputField:focus ~ .userIcon,
.__UIV_SCOPE__ #inputField:valid ~ .userIcon {
  transform: translateX(20px);
  opacity: 1;
}

.__UIV_SCOPE__ #inputField:focus,
.__UIV_SCOPE__ #inputField:valid {
  background-color: #ddd;
  transition-duration: .3s;
}
